@inlinable public func log1p(_ x: simd_double8) -> simd_double8 { lanewise(x, Double.libmLog1p) }
@inlinable public func log2(_ x: simd_double8) -> simd_double8 { lanewise(x, Double.libmLog2) }
@inlinable public func sin(_ x: simd_double8) -> simd_double8 { lanewise(x, Double.libmSin) }
@inlinable public func sinh(_ x: simd_double8) -> simd_double8 { lanewise(x, Double.libmSinh) }
@inlinable public func tan(_ x: simd_double8) -> simd_double8 { lanewise(x, Double.libmTan) }
@inlinable public func tanh(_ x: simd_double8) -> simd_double8 { lanewise(x, Double.libmTanh) }
@inlinable public func tgamma(_ x: simd_double8) -> simd_double8 { lanewise(x, Double.libmTgamma) }
@inlinable public func atan2(_ y: simd_double8, _ x: simd_double8) -> simd_double8 { lanewise(y, x, Double.libmAtan2) }
@inlinable public func fmod(_ x: simd_double8, _ y: simd_double8) -> simd_double8 { lanewise(x, y, Double.libmFmod) }
@inlinable public func hypot(_ x: simd_double8, _ y: simd_double8) -> simd_double8 { lanewise(x, y, Double.libmHypot) }
@inlinable public func nextafter(_ x: simd_double8, _ y: simd_double8) -> simd_double8 { lanewise(x, y, Double.libmNextafter) }
@inlinable public func pow(_ x: simd_double8, _ y: simd_double8) -> simd_double8 { lanewise(x, y, Double.libmPow) }
@inlinable public func remainder(_ x: simd_double8, _ y: simd_double8) -> simd_double8 { lanewise(x, y, Double.libmRemainder) }
@inlinable public func exp10(_ x: simd_double8) -> simd_double8 { lanewise(x, exp10Scalar) }
@inlinable public func sinpi(_ x: simd_double8) -> simd_double8 { lanewise(x, sinPi) }
@inlinable public func cospi(_ x: simd_double8) -> simd_double8 { lanewise(x, cosPi) }
@inlinable public func tanpi(_ x: simd_double8) -> simd_double8 { lanewise(x, tanPi) }
@inlinable public func sincos(_ x: simd_double8) -> (sin: simd_double8, cos: simd_double8) { (lanewise(x, Double.libmSin), lanewise(x, Double.libmCos)) }
@inlinable public func sincospi(_ x: simd_double8) -> (sin: simd_double8, cos: simd_double8) { (lanewise(x, sinPi), lanewise(x, cosPi)) }
@inlinable public func fma(_ x: simd_double8, _ y: simd_double8, _ z: simd_double8) -> simd_double8 { muladdFloat(x, y, z) }
@inlinable public func round(_ x: simd_double8) -> simd_double8 { x.rounded(.toNearestOrAwayFromZero) }
@inlinable public func isfinite(_ x: simd_double8) -> simd_long8 { mask(x) { $0.isFinite } }
@inlinable public func isinf(_ x: simd_double8) -> simd_long8 { mask(x) { $0.isInfinite } }
@inlinable public func isnan(_ x: simd_double8) -> simd_long8 { mask(x) { $0.isNaN } }
@inlinable public func isnormal(_ x: simd_double8) -> simd_long8 { mask(x) { $0.isNormal } }

